function loadOrder(modules) {
  const state = new Map();
  const order = [];
  function visit(name) {
    if (state.get(name) === "done") return true;
    if (state.get(name) === "loading") return false;
    state.set(name, "loading");
    for (const dep of modules[name]) {
      if (!visit(dep)) return false;
    }
    state.set(name, "done");
    order.push(name);
    return true;
