function debounceCalls(calls, wait) {
  const fired = [];
  let pending = null;
  for (const [time, value] of calls) {
    if (pending !== null && pending.due <= time) fired.push([pending.due, pending.value]);
    pending = { due: time + wait, value };
  }
  if (pending !== null) fired.push([pending.due, pending.value]);
  return fired;
}

js-spiral-matrix.solution:
function spiralOrder(grid) {
  const out = [];
  if (grid.length === 0) return out;
  let top = 0, bottom = grid.length - 1, left = 0, right = grid[0].length - 1;
  while (top <= bottom && left <= right) {
    for (let c = left; c <= right; c++) out.push(grid[top][c]);
    top++;
    for (let r = top; r <= bottom; r++) out.push(grid[r][right]);
    right--;
    if (top <= bottom) {
      for (let c = right; c >= left; c--) out.push(grid[bottom][c]);
      bottom--;
    }
    if (left <= right) {
      for (let r = bottom; r >= top; r--) out.push(grid[r][left]);
      left++;
    }
  }
  return out;
}

